$expand = function($item) {
    $title = $item['title']; $grade = $item['grade']; $focus = $item['focus'];
    $practice = function($raw, $directions) {
        list($question, $answer) = array_map('trim', explode('|', $raw, 2));
        return $directions . ' || ' . $question . ' | ' . $answer
            . ' | Choose a model and label what each number means before calculating.'
            . ' | Show one small step at a time and check that the operation matches the story or equation.'
            . ' | Use the lesson model, complete the calculation, and check that the result answers the question.';
    };
    return [
        'title'=>$title,
        'subtitle'=>'Build strong operations and algebraic thinking by learning to ' . $focus . '.',
        'essential_question'=>'How can a picture, equation, or pattern help us ' . $focus . '?',
        'learning_targets'=>"I can explain what the numbers and symbols mean.\nI can choose a picture, object model, equation, or pattern that fits the problem.\nI can solve and check my answer.",
        'vocabulary'=>str_replace('; ', "\n", $item['vocab']),
        'worked_examples'=>$item['example'],
        'common_mistakes'=>"Choosing an operation from one keyword | Read the whole situation and decide what happens to the amount.\nWriting an answer without a model or equation | Show a picture, objects, or a number sentence that matches.\nStopping without checking | Use the inverse operation, recount, or substitute the answer to check.",
        'real_life'=>'Operations and algebraic thinking help us share objects, compare choices, count groups, find missing amounts, and describe patterns in everyday situations.',
        'videos'=>$title . ' | https://www.khanacademy.org/math/cc-' . (stripos($grade, 'Kindergarten') !== false ? 'kindergarten' : strtolower(str_replace(' ', '-', $grade))) . '-math',
        'video_chapters'=>"0:00 | Understand the problem\n1:00 | Build or draw a model\n2:15 | Write the equation or rule\n3:15 | Solve and check",
        'practice_warmup'=>$practice($item['warm'], 'Use a quick picture or equation. Explain what the numbers mean.'),
        'guided_practice'=>$practice($item['guided'], 'Follow the steps. Build or draw the situation, write an equation, and solve.'),
        'independent_practice'=>$practice($item['independent'], 'Choose a model, show your work, and enter your final answer.'),
        'challenge_practice'=>$item['challenge'],
        'master_it'=>"I can choose an operation or rule that matches the problem.\nI can use correct mathematical vocabulary to explain my model.\nI can check whether my answer is reasonable.",
        'mastery_questions'=>"Which action helps you understand a problem first? | Guess the answer ; Identify what each number means ; Ignore the question ; Choose the largest number | B\nWhat does an equal sign mean? | Add next ; The left side is larger ; Both sides have the same value ; Stop working | C\nWhich is a good way to check an answer? | Use a related or inverse operation ; Change the question ; Erase the model ; Pick a new number | A\nWhy should a model match the question? | To make it colorful ; To show the mathematical relationship ; To avoid numbers ; To make every answer the same | B\nWhat should a final answer include in a story problem? | Only a symbol ; A number that answers the question, with units when needed ; Every number from the story ; A new question | B",
        'parent_summary'=>'Students learn to represent operations and patterns with objects, drawings, equations, and clear mathematical language. The lesson emphasizes understanding before memorizing a procedure.',
